head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.fn_SetPar, scwin.strCdSch;
scwin.vScrenID = "ULDSTF92015.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_rdochange = function() {
    if ($c.stf.getObjectValue(rdo_searchType) == "1") {
        $c.stf.showObj(panel_1, true);
        $c.stf.showObj(panel_2, false);
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(label_9, false);
    } else {
        $c.stf.showObj(panel_1, false);
        $c.stf.showObj(panel_2, true);
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(label_9, true);
    }
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listZipCd";
    url += "&inputMessageId=ZIPCD_OUT&outputMessageId=ZIPCD_OUT";
    url += "&SEARCHTYPE=" + $c.stf.getObjectValue(rdo_searchType) + "&SEARCHDTL_1=" + $c.stf.getObjectValue(txb_Search_1) + "&SEARCHDTL_2=" + $c.stf.getObjectValue(txb_Search_2);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.fn_checkSearchWord = function(pWord, type) {
    var word = $c.stf.trim(pWord);
    var reg = new RegExp(/[%]/g);
    if (reg.test(pWord)) {
        $c.win.alert("%는 사용할 수 없습니다.");
        return false;
    }
    if (word.length < 2) {
        $c.win.alert(type + "은 두글자 이상 입력되어야 합니다.");
        return false;
    }
    return true;
};
scwin.txb_Search_1_onkeydown = function() {
    if (event.keyCode == 13) {
        if ($c.stf.getObjectValue(rdo_searchType) == "1") {
            if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_1))) {
                $c.win.alert("검색할 도로명을 입력해 주세요.");
                txb_Search_1.focus();
                return false;
            }
            if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_1), "도로명")) {
                txb_Search_1.focus();
                return false;
            }
        } else {
            if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_2))) {
                $c.win.alert("검색할 건물명을 입력해 주세요.");
                txb_Search_2.focus();
                return false;
            }
            if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_2), "건물명")) {
                txb_Search_2.focus();
                return false;
            }
        }
        scwin.fn_list_sync();
    }
};
scwin.txb_Search_2_onkeydown = function() {
    if (event.keyCode == 13) {
        if ($c.stf.getObjectValue(rdo_searchType) == "1") {
            if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_1))) {
                $c.win.alert("검색할 도로명을 입력해 주세요.");
                txb_Search_1.focus();
                return false;
            }
            if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_1), "도로명")) {
                txb_Search_1.focus();
                return false;
            }
        } else {
            if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_2))) {
                $c.win.alert("검색할 건물명을 입력해 주세요.");
                txb_Search_2.focus();
                return false;
            }
            if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_2), "건물명")) {
                txb_Search_2.focus();
                return false;
            }
        }
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 " + rowcount + " 건");
    if (scwin.strCdSch != "") {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (scwin.strCdSch == dts_List.getCellData(i, 1)) {
                dts_List.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strCdSch = "";
    }
    $c.cm.ShowWin(grd_List);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.rdo_searchType_OnSelChange = function() {
    scwin.fn_rdochange();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), 'ZIPCD');
        arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), 'ADDR');
        arrPar[2] = dts_List.getCellData(dts_List.getRowPosition(), 'ZIPCD_SEQ');
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.img_Search_onclick = function() {
    if ($c.stf.getObjectValue(rdo_searchType) == "1") {
        if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_1))) {
            $c.win.alert("검색할 도로명을 입력해 주세요.");
            txb_Search_1.focus();
            return false;
        }
        if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_1), "도로명")) {
            txb_Search_1.focus();
            return false;
        }
    } else {
        if ($c.ut.cIsNull($c.stf.getObjectValue(txb_Search_2))) {
            $c.win.alert("검색할 건물명을 입력해 주세요.");
            txb_Search_2.focus();
            return false;
        }
        if (!scwin.fn_checkSearchWord($c.stf.getObjectValue(txb_Search_2), "건물명")) {
            txb_Search_2.focus();
            return false;
        }
    }
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_rdochange();
    window.document.body.scroll = "no";
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    //fn_list_sync();
    txb_Search_1.focus();
};
